    regularization_id integer NOT NULL,
    employee_id integer,
    date date NOT NULL,
    original_clock_in time without time zone,
    original_clock_out time without time zone,
    requested_clock_in time without time zone NOT NULL,
    requested_clock_out time without time zone NOT NULL,
    reason text NOT NULL,
    status character varying(20) DEFAULT 'pending'::character varying,
    approved_by integer,
    approved_at timestamp without time zone,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT attendance_regularization_status_check CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'approved'::character varying, 'rejected'::character varying])::text[])))
);


